import pathlib,argparse,hashlib,json,sys
from fractions import Fraction as F
P=pathlib.Path(__file__).resolve().parent
H=lambda b:hashlib.sha256(b).hexdigest()
def check(source,fixture,out):
 s=json.loads(source.read_text());d=json.loads(fixture.read_text());c=json.loads((P/'CONTRACT.json').read_text());q=F(d['heat_input_kJ'])*1000;n=F(d['mass_g'])/F(s['molecular_weight_value']);cp=F(s['property_value']);result=json.loads((out/'05_result.json').read_text());quantity=json.loads((out/'04_quantity.json').read_text());norm=json.loads((out/'03_normalized.json').read_text());math=F(result['temperature_change_K'])==q/(n*cp) and F(quantity['amount_mol'])==n and F(norm['heat_input_J'])==q;src=H(source.read_bytes())==c['source_record_sha256'] and H((P/'source_extract.txt').read_bytes())==c['source_extract_sha256'] and d.get('source_sha256')==c['source_record_sha256'];conditions=d.get('material')==s['material'] and d.get('phase')==s['phase'] and d.get('reference_temperature_K')==s['temperature_K'] and d.get('reference_pressure')==s['pressure'];units=d.get('heat_unit')=='kJ' and d.get('cp_unit')==s['property_unit'] and d.get('molar_mass_unit')=='g/mol';frozen=H(fixture.read_bytes())==c['fixture_sha256'];expected=json.loads((P/'expected_hashes.json').read_text());hashes={n:H((out/n).read_bytes()) for n in expected};identity=hashes==expected;commit=json.loads((out/'07_commitment.json').read_text());consistent=commit['artifacts']=={n:H((out/n).read_bytes()) for n in expected if n!='07_commitment.json'};status='PASS' if all([math,src,conditions,units,frozen,identity,consistent]) else 'REJECT';return {'status':status,'math':math,'source_bound':src,'conditions':conditions,'units':units,'fixture_frozen':frozen,'hashes_match':identity,'commitment_consistent':consistent}
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--source',type=pathlib.Path,default=P/'source_record.json');a.add_argument('--fixture',type=pathlib.Path,default=P/'fixture.json');a.add_argument('--out',type=pathlib.Path,required=True);z=a.parse_args();r=check(z.source,z.fixture,z.out);print(json.dumps(r,sort_keys=True));sys.exit(0 if r['status']=='PASS' else 1)
